#!/usr/bin/env python3
"""
Attrium CleanState (Panic) & Fault-Tolerant RenderSafeGuard Installer (Fabric 1.21.11)
- Installs CleanStateManager.java, RenderSafeGuard.java, updated NotificationsModule.java,
  HudManager.java (per-widget try-catch isolation), and GlassClickGuiScreen.java
  (Client tab Clean State button, Panic Key pill, Restore on Re-Press toggle, & acc.json persistence).
"""
import base64
import os
import sys

FILES_B64 = {
    "attrium/ru/utils/render/RenderSafeGuard.java": "",
    "attrium/ru/manager/CleanStateManager.java": "",
    "attrium/ru/api/module/impl/visual/NotificationsModule.java": "",
    "attrium/ru/manager/HudManager.java": "",
    "attrium/ru/screens/GlassClickGuiScreen.java": "",

}


def main():
    cwd = os.getcwd()
    src_root = os.path.join(cwd, "src", "main", "java")
    if not os.path.isdir(src_root):
        print(f"[ERROR] Run this script from your project root (missing {src_root}).")
        sys.exit(1)
    for rel_path, b64_data in FILES_B64.items():
        out_path = os.path.join(src_root, *rel_path.split("/"))
        os.makedirs(os.path.dirname(out_path), exist_ok=True)
        with open(out_path, "wb") as f:
            f.write(base64.b64decode(b64_data))
        print(f"[OK] Wrote {rel_path}")
    print("\nCleanState & RenderSafeGuard installed! Run: ./gradlew build --no-daemon")


if __name__ == "__main__":
    main()